"""
Regenerate tests/fixtures/vault_v2_golden.json.

    cd mcp-server && python tests/fixtures/gen_vault_v2_golden.py

The fixture is the contract between three implementations of the same format:
the MCP server (Python), the browser (TypeScript) and, for the digest, the
backend (Java). It is generated here because the Python side is the one this
repo can run without a browser, and it is *asserted* on both sides:

  * mcp-server/tests/test_vault_v2_golden.py
  * frontend/src/__tests__/vaultV2Golden.test.ts

Every value is deterministic: fixed keys, fixed salts, fixed IVs. Nothing here
depends on a random draw, so a regenerated fixture that differs from the
committed one means the format changed, not that the dice moved.

Run it inside the test image (it imports mcp_server, which needs fastmcp):

    docker run --rm -v "$PWD:/src" -w /src mcpd2b-test \
        python tests/fixtures/gen_vault_v2_golden.py
"""

import base64
import hashlib
import json
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", ".."))

from mcp_server import (  # noqa: E402
    _vault_derive_kek,
    _vault_encrypt_v2_field,
    _vault_fingerprint,
    _vault_field_plaintext,
    _vault_v2_aad,
    _vault_v2_parse_kdf,
    _vault_wrap_dek,
)

OUT_PATH = os.path.join(os.path.dirname(__file__), "vault_v2_golden.json")

FIXED_DEK = bytes(range(32))
FIXED_IV = bytes(range(12))
KEY_ID = _vault_fingerprint(FIXED_DEK)
ENTRY_UUID = "3f9a1c22-7777-4b0e-9a11-0d0d0d0d0d0d"
USER_ID = 7

SALT_16 = bytes(range(16))
SALT_32 = bytes(range(32, 64))

# The values the two languages have historically disagreed about. Each one is
# here because a real client got it wrong at some point.
TEXT_VECTORS = [
    "hunter2",
    "Příšerně žluťoučký kůň — heslo",
    "😀 pass — 😀",
    'quote " backslash \\ newline\n tab\t',
    "\x00\x01\x1f\x7f\u2028\u2029",
    "\ud800 lone high surrogate",
    "\udc00\udfff",
    "",
    "007",
]


def _b64(raw: bytes) -> str:
    return base64.b64encode(raw).decode("ascii")


def _hex(raw: bytes) -> str:
    return raw.hex()


def build() -> dict:
    fixture = {
        "format": "w4ai-vault-v2-golden/1",
        "note": (
            "Cross-language vectors for the vault v2 wire format (WIKI4AI-197 D2b). "
            "Generated by tests/fixtures/gen_vault_v2_golden.py and asserted by both "
            "mcp-server/tests/test_vault_v2_golden.py and "
            "frontend/src/__tests__/vaultV2Golden.test.ts. Do not hand-edit."
        ),
        "sha256_hex": [],
        "pbkdf2_sha256": [],
        "json_text": [],
        "aad": [],
        "field": [],
        "wrap": [],
    }

    # ── h = hex(SHA-256(UTF-8(password))) — v1's preprocessing, local-only in v2
    for text in ["correct horse battery staple", "Příšerně kůň", "😀"]:
        digest = hashlib.sha256(text.encode("utf-8")).hexdigest()
        fixture["sha256_hex"].append({"input": text, "hex": digest})

    # ── PBKDF2-HMAC-SHA256: the KEK (raw password) and v1's K1 (h)
    h = hashlib.sha256("correct horse battery staple".encode("utf-8")).hexdigest()
    kdf_inputs = [
        ("correct horse battery staple", SALT_16, 1_000),
        (h, SALT_16, 100_000),
        ("Příšerně žluťoučký kůň 😀", SALT_32, 600_000),
    ]
    for password, salt, iterations in kdf_inputs:
        key = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, iterations, 32)
        fixture["pbkdf2_sha256"].append(
            {
                "password": password,
                "salt_b64": _b64(salt),
                "iterations": iterations,
                "key_hex": _hex(key),
            }
        )

    # ── the plaintext bytes: JSON.stringify, raw UTF-8, lone surrogates escaped
    for value in TEXT_VECTORS:
        plaintext = _vault_field_plaintext(value)
        fixture["json_text"].append({"value": value, "utf8_hex": _hex(plaintext)})

    # ── the AAD, including the uuid lowercasing
    for field in ("username", "password", "notes"):
        aad = _vault_v2_aad(USER_ID, ENTRY_UUID, field, KEY_ID)
        fixture["aad"].append(
            {
                "user_id": USER_ID,
                "entry_uuid": ENTRY_UUID,
                "field": field,
                "key_id": KEY_ID,
                "utf8_hex": _hex(aad),
            }
        )
    aad_upper = _vault_v2_aad(USER_ID, ENTRY_UUID.upper(), "password", KEY_ID)
    fixture["aad"].append(
        {
            "user_id": USER_ID,
            "entry_uuid": ENTRY_UUID.upper(),
            "field": "password",
            "key_id": KEY_ID,
            "utf8_hex": _hex(aad_upper),
        }
    )

    # ── a whole field: key + IV + AAD in, one Base64 blob out
    for index, value in enumerate(TEXT_VECTORS):
        iv = bytes((index * 7 + i) % 256 for i in range(12))
        field = ("password", "username", "notes")[index % 3]
        packed = _vault_encrypt_v2_field(
            value, FIXED_DEK, USER_ID, ENTRY_UUID, field, KEY_ID, iv=iv
        )
        fixture["field"].append(
            {
                "name": "field-%02d-%s" % (index, field),
                "dek_hex": _hex(FIXED_DEK),
                "iv_hex": _hex(iv),
                "user_id": USER_ID,
                "entry_uuid": ENTRY_UUID,
                "field": field,
                "key_id": KEY_ID,
                "value": value,
                "packed_b64": packed,
            }
        )

    # ── the wrapped DEK: iv || ciphertext || tag, no AAD
    for index, salt in enumerate((SALT_16, SALT_32)):
        kek = hashlib.pbkdf2_hmac(
            "sha256", "correct horse battery staple".encode("utf-8"), salt, 1_000, 32
        )
        iv = bytes((0x30 + index * 0x10 + i) % 256 for i in range(12))
        fixture["wrap"].append(
            {
                "kek_hex": _hex(kek),
                "iv_hex": _hex(iv),
                "dek_hex": _hex(FIXED_DEK),
                "wrapped_b64": _vault_wrap_dek(kek, FIXED_DEK, iv=iv),
            }
        )

    # The KDF string the backend stores, and what it parses to. Pinned here so a
    # server that changes the work factor is noticed by the client tests too.
    fixture["kdf_params"] = {
        "kdf_json": '{"alg":"PBKDF2-HMAC-SHA256","iter":600000,"dkLen":256}',
        "iterations": 600_000,
        "key_bytes": 32,
    }
    return fixture


def main() -> int:
    fixture = build()
    with open(OUT_PATH, "w", encoding="utf-8") as handle:
        # ensure_ascii keeps the fixture itself pure ASCII, so a lone surrogate
        # value is stored as an escape and both readers see the same character.
        json.dump(fixture, handle, indent=2, sort_keys=True)
        handle.write("\n")
    counts = {key: len(value) for key, value in fixture.items() if isinstance(value, list)}
    print("wrote", OUT_PATH, counts)
    # Sanity: the generator's own defaults agree with the client's fallbacks.
    assert _vault_v2_parse_kdf(fixture["kdf_params"]["kdf_json"]) == (
        fixture["kdf_params"]["iterations"],
        fixture["kdf_params"]["key_bytes"],
    )
    assert _vault_derive_kek("x", _b64(SALT_16), 1_000, 32)
    return 0


if __name__ == "__main__":
    sys.exit(main())
